import { z } from 'zod/v3';
import {
  CONTEXT_ASSET_MAX_ITEMS,
  contextAssetInputSchema,
  runLabelSchema,
  startVariantsBriefContent,
  VARIANT_COUNT_MAX,
  VARIANT_COUNT_MIN,
} from '../agent-variants/contracts';
import {
  GuidanceSelectionSchema,
  type GuidanceSelection,
} from '../types/guidance';
import {
  REFERENCE_PICK_LIMIT,
  REFERENCE_PICK_REASON_CHARACTERS,
} from '../types/design-profile';

const DIRECTION_TITLE_MAX_WORDS = 5;
const DIRECTION_SUBTITLE_MAX_WORDS = 10;

export const variantInitiatorSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('human') }),
  z.object({
    kind: z.literal('agent'),
    agent: z.enum(['claude', 'codex', 'cursor', 'grokbot', 'unknown']),
    model: z.string().max(200).optional(),
  }),
]);

export const workerSelectionSchema = z.object({
  provider: z.enum(['claude', 'codex', 'cursor']).optional(),
  model: z.string().min(1).max(200).optional(),
});

const inlineVariantBriefSchema = startVariantsBriefContent.superRefine(
  (brief, context) => {
    const titleWordCount = brief.label.trim().split(/\s+/).length;
    const subtitleWordCount = brief.body.trim().split(/\s+/).length;
    if (titleWordCount > DIRECTION_TITLE_MAX_WORDS) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['label'],
        message: 'direction titles must contain at most 5 words',
      });
    }
    if (subtitleWordCount > DIRECTION_SUBTITLE_MAX_WORDS) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['body'],
        message: 'direction subtitles must contain at most 10 words',
      });
    }
  },
);

const guidanceSelectionSchema = z
  .unknown()
  .transform((value, context): GuidanceSelection => {
    const parsed = GuidanceSelectionSchema.safeParse(value);
    if (parsed.success) return parsed.data;
    for (const { message, path } of parsed.error.issues) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        message,
        path: path.filter((key) => typeof key !== 'symbol'),
      });
    }
    return z.NEVER;
  });

export const referencePicksSchema = z
  .object({
    profileId: z.string().uuid(),
    picks: z
      .array(
        z
          .object({
            key: z.string().trim().min(1).max(200),
            reason: z
              .string()
              .trim()
              .min(1)
              .max(REFERENCE_PICK_REASON_CHARACTERS),
          })
          .strict(),
      )
      .min(1)
      .max(REFERENCE_PICK_LIMIT)
      .refine(
        (picks) => new Set(picks.map((pick) => pick.key)).size === picks.length,
        { message: 'Each reference pick must use a distinct key' },
      ),
  })
  .strict();

export const inlineVariantRequestSchema = z
  .object({
    guidanceSelection: guidanceSelectionSchema.optional(),
    count: z.number().int().min(VARIANT_COUNT_MIN).max(VARIANT_COUNT_MAX),
    mode: z.enum(['existing', 'zero_to_one']).optional(),
    profile: z.enum(['auto', 'off']).optional(),
    runLabel: runLabelSchema,
    fidelity: z.enum(['low', 'medium', 'high']).optional(),
    briefs: z
      .array(inlineVariantBriefSchema)
      .min(VARIANT_COUNT_MIN)
      .max(VARIANT_COUNT_MAX)
      .optional(),
    contextAssets: z
      .array(contextAssetInputSchema)
      .min(1)
      .max(CONTEXT_ASSET_MAX_ITEMS)
      .optional(),
    referencePages: z
      .array(
        z.object({
          url: z.string().url().max(2048),
          note: z.string().min(1).max(500).optional(),
        }),
      )
      .min(1)
      .max(3)
      .optional(),
    referenceVideos: z
      .array(
        z.object({
          path: z.string().min(1).max(2048),
          note: z.string().min(1).max(500).optional(),
        }),
      )
      .min(1)
      .max(2)
      .optional(),
    referencePicks: referencePicksSchema.optional(),
  })
  .superRefine((request, context) => {
    if (request.briefs && request.briefs.length !== request.count) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['briefs'],
        message: 'briefs length must match count',
      });
    }
    if (request.briefs) {
      const labels = request.briefs.map((brief) =>
        brief.label.trim().toLowerCase().replace(/\s+/g, ' '),
      );
      if (new Set(labels).size !== labels.length) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['briefs'],
          message: 'brief labels must be distinct',
        });
      }
    }
  });
